        // Store initial balances
        uint256 initialAttackerBalance = token.balanceOf(attacker);
        LuffyInu tokenContract = LuffyInu(TARGET);
        address pair = tokenContract.uniswapV2Pair();
        uint256 initialPairBalance = tokenContract.balanceOf(pair);

