        uint256 pairTokensLost = initialPairBalance - finalPairBalance;

        console.log("Tokens received by attacker:", tokensReceived);
        console.log("Tokens lost by pair:", pairTokensLost);
        console.log("Extra tokens lost by pair (marketing + burn):", pairTokensLost - tokensReceived);

        // The exploit is demonstrated: pair lost more tokens than attacker received
        // due to marketing/burn fees deducted from pair balance
    }



    // ─── Receive ETH ─────────────────────────────────────────
